-- GENERATED by `wfj generate` from data/gossip/gossip-5f.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["5f03b76e3f376ddb"] = { "Tenetevi pronti!", "." },
  ["5f0b5e96ee852361"] = { "Ci siamo, gente. Guardatevi le spalle...", "." },
  ["5f11176fb33ea092"] = { "Una parte sempre più grande di Kalimdor si sta trasformando nel paesaggio distorto alla nostra sinistra, e le creature che ci vivono NON sono amichevoli. Guarda dove metti i piedi.", "." },
  ["5f1a58a2f928dd70"] = { "Guardati intorno. C'è così tanta bellezza qui. Il vento sul viso, il cielo azzurro sopra la testa. È tutto così luminoso e vivo, eppure sì, è anche piuttosto cupo. Sembra una prigione. Una prigione in cui le guardie se ne sono andate e hanno lasciato i prigionieri nelle celle a cavarsela da soli.", "." },
  ["5f1af88608e4e7ce"] = { "È vero, giovane {race}: noi e l'⟦Alliance=Alleanza⟧ abbiamo raccolto e preparato tutto ciò che ci servirà per l'imminente conflitto ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Proprio ora tutto viene spedito alla ⟦Cenarion Hold=Fortezza Cenariana⟧, e le ultime cose dovrebbero arrivare entro un giorno. Quando tutto sarà pronto, qualcuno dovrà suonare il gong sull'Altare dello Scarabeo per aprire i cancelli e dare inizio alla guerra.", "." },
  ["5f1d8b5f779acf7e"] = { "Hai scelto saggiamente, {name}. Cerca ⟦Kergul Bloodaxe=Kergul Scurerossa⟧ sull'⟦Hunter Rise=Altura dei Cacciatori⟧. Ti assisterà nel tuo viaggio verso la ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", "." },
  ["5f2034b3dc0f0dc5"] = { "I giorni trascorsi qui ad Azshara non sono tra i nostri migliori e più gloriosi, ma siamo ancora giovani e il sangue ci scorre ancora nelle vene: qui troveremo la vittoria. È solo questione di tempo.", "." },
  ["5f20f53d54289d3b"] = { "Dammi la tartaruga da sella!", "." },
  ["5f2212f4977340e4"] = { "Il magistrato è troppo ben protetto. Ritirata!", "." },
  ["5f236d6c4cc58b86"] = { "Ehi ehi ehi! Sono qui per promuovere un favoloso torneo di pesca a Rovotorto, ma per sopravvivere laggiù ci vuole la scorza dura, e serve abbastanza abilità nella pesca per pescare in quelle acque.\n\nTorna più tardi, quando avrai più esperienza!", "." },
  ["5f2387c0ec711c1d"] = { "Capitano Brightsun, {name} qui presente mi ha liberato! {name}, di certo il capitano premierà il tuo coraggio.", "." },
  ["5f2aa8a646530c7c"] = { "Grazie, Omarion. Oggi hai incassato un colpo fatale per la squadra.", "." },
  ["5f34f50e182aec7a"] = { "L'oscurità non ti accoglie, {class}. Smettila di blaterare e togliti dalla mia vista! Vattene!", "." },
  ["5f4b9c724127e243"] = { "Prendi le tue cose, {name}! Mi è appena arrivata notizia da Nilith Lokrav, nella ⟦Searing Gorge=Gorgia Rovente⟧, che l'Undermarket ha avviato le operazioni nel cuore della Caldera Magmatica. Trova Nilith Lokrav nella ⟦Searing Gorge=Gorgia Rovente⟧ e fatti dare i dettagli!", "." },
  ["5f53f720f190263d"] = { "Imbecille! Non hai imparato il sistema decimale Dewey? Sono passati 3.000 anni da quando hai iniziato a lavorare per noi! Buffone incompetente.", "." },
  ["5f55ba5ff8c6ccfd"] = { "Volano su ali oscurissime. Preparati ad affrontare la tua fine!", "." },
  ["5f5657d873adb581"] = { "%s esamina meticolosamente il grande vaso.", "." },
  ["5f597df54c8bd268"] = { "Tu hai i soldi e noi abbiamo il cibo. Cosa aspetti?!", "." },
  ["5f5aadee64752476"] = { "Ho ricevuto gran parte del mio addestramento nelle armi da ⟦Ilyenia Moonfire=Ilyenia Lunardente⟧, alla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧. Faresti bene a cercarla, se desideri imparare a usare una nuova arma.", "." },
  ["5f5eddae58a01e4b"] = { "Cenere alla cenere!", "." },
  ["5f67994fe9702b4f"] = { "Io... credo di vedere Blue...", "." },
  ["5f6c2558b002a989"] = { "Salve, salve, Amy. È bello essere di nuovo a ⟦Lakeshire=Borgolago⟧ e rivederti, mia signora.", "." },
  ["5f6d5d97b0b95882"] = { "Ho appena visto uno del Flagello! Uccidilo!", "." },
  ["5f769cf26b576bfd"] = { "Stiamo perdendo tempo. Mettiamoci in marcia.", "." },
  ["5f7fb2de304ba300"] = { "%s lancia un ruggito di sfida a {name}!", "." },
  ["5f800a0154b19146"] = { "Mi sento male.", "." },
  ["5f8056c597c2d57c"] = { "Vorrei che potessi semplicemente prendermi in braccio e portarmi, {name}.", "." },
  ["5f81e0e82b348ec1"] = { "Se desideri imparare le vie dell'Erbalismo, devi andare a ⟦Thunder Bluff=Picco del Tuono⟧. Segui la strada a nord fuori dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ e prendi l'ascensore fino in cima all'altura. Lì puoi chiedere ulteriore aiuto a un ⟦Bluffwatcher=Guardiano del Picco⟧.", "." },
  ["5f888d76370ca6e7"] = { "Un potente qiraji noto come generale Rajaxx avrebbe guidato l'incursione iniziale a ⟦Silithus=Silitus⟧. Solo uno si sarebbe frapposto sul suo cammino: un elfo della notte di nome Staghelm. Lo chiamano Khar'sis, o «mano della terra», nella lingua nativa dei Qiraji.", "." },
  ["5f8b4f6a315e111c"] = { "Nel tempo prima del tempo, quando il mondo era ancora nella sua infanzia, su questo stesso suolo infuriò una battaglia tra un ⟦Titan=Titano⟧ e un essere di malvagità e potere inimmaginabili. La profezia non chiarisce se il ⟦Titan=Titano⟧ sia stato sconfitto in quella battaglia, ma mostra che un ⟦Titan=Titano⟧ cadde. Anche un Dio Antico era caduto... o almeno così si credeva.", "." },
  ["5f9414c15bc7e7f4"] = { "Salve, {class}. Qui raccolgo bende di lino per lo sforzo bellico di ⟦Ahn'Qiraj=Ahn'qiraj⟧, uno sforzo che metterà tutti noi alla prova, ma ci renderà più forti per la guerra che verrà. Ti assicuro che ogni benda che deciderai di donare sarà usata bene per salvare la vita dei nostri soldati quando sarà il momento. Me ne servono $2077w, e finora ne ho raccolte $2076w. Ci aiuterai?", "." },
  ["5fa4b114e4ffa541"] = { "Il rituale è già iniziato!", "." },
  ["5fa605ad2c7f7202"] = { "Non posso crederci! Hai distrutto il mio branco... Ora affronta la mia ira!", "." },
  ["5fa90753d0f29ca4"] = { "Be', ora che me lo dici, sì, ieri pomeriggio ho visto una cosa che mi è sembrata un po' strana!\n\nStavo correndo vicino a delle vecchie rovine troll a sud-est di qui; be', non proprio correndo, più che altro saltellando... La sabbia scotta da morire!\n\nComunque, stavo saltellando vicino alle rovine quando ho notato un accampamento. Mi sembra un posto strano per accamparsi, se vuoi saperlo... Avrei curiosato ancora un po', ma uno di quegli enormi avvoltoi pazzi mi è corso dietro e ho dovuto filarmela.", "." },
  ["5fabeac1ba8bc2b4"] = { "Qui alla loggia dei Farstrider apprezziamo le abilità di caccia sopra ogni cosa. Vuoi ottenere la mia approvazione? Dovrai guadagnartela.\n\nMi sembri all'altezza della sfida, <ragazzo/ragazza>!", "." },
  ["5fac5584e56e8f59"] = { "Anch'io ho i miei limiti! Va' a parlare con Lavinia Crowe a ⟦Undercity=Sepulcra⟧, se vuoi proseguire il tuo addestramento.", "." },
  ["5fb86262138b8dfd"] = { "%s perde energia e si spegne!", "." },
  ["5fca750873c472ea"] = { "%s, in preda all'alcol, sbaglia un Dardo d'Ombra!", "." },
  ["5fd3449fdbc990fe"] = { "%s sbuffa.", "." },
  ["5fd7f3825b992f7b"] = { "Sono partiti per ⟦Gadgetzan=Meccania⟧ un po' di tempo fa per portarci delle provviste. Sinceramente, avrei dato almeno quattro dita per poter strisciare dentro uno degli zaini di Dadanga e lasciare questo posto dimenticato da tutti.", "." },
  ["5fdad2e1b3a0cc49"] = { "%s si sveglia!", "." },
  ["5fe646e2681fc15d"] = { "Mi sto spostando all'interno dell'edificio", "." },
  ["5febccb7d64c9fbd"] = { "Noi del ⟦Refuge Pointe=Fosso dei Rifugiati⟧ teniamo uno dei pochi lembi rimasti del territorio di Stromgarde negli ⟦Arathi Highlands=Altopiani d'Arathi⟧. E stiamo perdendo terreno...\n\nSe hai qualcosa da dirmi, spero siano buone notizie.", "." },
  ["5fed548753d37b2d"] = { "NON PUÒ ESSERE!!! Rend, occupati di questi insetti.", "." },
  ["5fee1e539e06df7f"] = { "Ti prego, addestrami.", "." },
  ["5ff0baf0a9dd3096"] = { "Il Dun Baldar North Bunker è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ lo distruggerà!", "." },
  ["5ff5cd7a7de54035"] = { "<Kharan sospira.>\n\nSuppongo... suppongo che tu abbia ragione.\n\nGor'shak mi ha detto che il tuo Capoguerra ha grandi progetti. Progetti che potrebbero cambiare il modo in cui l'⟦Alliance=Alleanza⟧ e l'⟦Horde=Orda⟧ si rapportano. Cosa ne sai?", "." },
  ["5ffb2e6194623326"] = { "Eccellente!\n\nIl totem che creerò per te è più di un simbolo del tuo rango di {class}: ha anche altri poteri. Uno degli usi del totem è come focus per gli incantesimi. Quegli incantesimi sono legati alla terra e, man mano che acquisirai sempre più saggezza, ti saranno resi accessibili altri poteri della terra.\n\nGli istruttori sapranno quando sarai pront<o/a> per conoscenze più grandi.\n\nMa per ora prendi questo totem della terra e una pergamena che ti insegnerà la tua prima abilità.", "." },
})
